use super::consts::DEFAULT_HEIGHT;
use super::consts::DEFAULT_WIDTH;

/// Public sizing policy for GPUI chart builders.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ChartSize {
    /// Fill the parent while keeping stable minimum dimensions for plot layout.
    Fill {
        min_width: f32,
        min_height: f32,
        aspect_ratio: Option<f32>,
    },
    /// Use an explicit fixed pixel size.
    Fixed { width: f32, height: f32 },
}

impl Default for ChartSize {
    fn default() -> Self {
        Self::Fill {
            min_width: DEFAULT_WIDTH,
            min_height: DEFAULT_HEIGHT,
            aspect_ratio: None,
        }
    }
}

impl ChartSize {
    /// Create fill sizing with default minimum dimensions.
    pub fn fill() -> Self {
        Self::default()
    }

    /// Create fixed pixel sizing.
    pub fn fixed(width: f32, height: f32) -> Self {
        Self::Fixed { width, height }
    }

    /// Set minimum dimensions while preserving the current sizing policy.
    pub fn min_size(self, min_width: f32, min_height: f32) -> Self {
        match self {
            Self::Fill { aspect_ratio, .. } => Self::Fill {
                min_width,
                min_height,
                aspect_ratio,
            },
            Self::Fixed { .. } => Self::Fill {
                min_width,
                min_height,
                aspect_ratio: None,
            },
        }
    }

    /// Set the preferred chart aspect ratio for fill layouts.
    pub fn aspect_ratio(self, aspect_ratio: f32) -> Self {
        match self {
            Self::Fill {
                min_width,
                min_height,
                ..
            } => Self::Fill {
                min_width,
                min_height,
                aspect_ratio: Some(aspect_ratio),
            },
            Self::Fixed { width, height } => Self::Fill {
                min_width: width,
                min_height: height,
                aspect_ratio: Some(aspect_ratio),
            },
        }
    }

    /// Return the dimensions used for deterministic plot geometry.
    pub fn layout_dimensions(self) -> (f32, f32) {
        match self {
            Self::Fill {
                min_width,
                min_height,
                aspect_ratio,
            } => {
                let (mut width, mut height) = (min_width, min_height);
                if let Some(ratio) = aspect_ratio
                    && ratio.is_finite()
                    && ratio > 0.0
                    && width.is_finite()
                    && height.is_finite()
                    && width > 0.0
                    && height > 0.0
                {
                    let current = width / height;
                    if current < ratio {
                        width = height * ratio;
                    } else {
                        height = width / ratio;
                    }
                }
                (width, height)
            }
            Self::Fixed { width, height } => (width, height),
        }
    }
}

pub(crate) fn apply_chart_size(mut el: gpui::Div, size: ChartSize) -> gpui::Div {
    use gpui::Styled as _;

    match size {
        ChartSize::Fill { .. } => {
            let (layout_width, layout_height) = size.layout_dimensions();
            el = el
                .w_full()
                .h_full()
                .min_w(gpui::px(layout_width))
                .min_h(gpui::px(layout_height));
        }
        ChartSize::Fixed { .. } => {
            let (layout_width, layout_height) = size.layout_dimensions();
            el = el.w(gpui::px(layout_width)).h(gpui::px(layout_height));
        }
    }

    el
}

pub(crate) fn resolved_chart_dimensions(size: ChartSize) -> (f32, f32) {
    size.layout_dimensions()
}

#[cfg(test)]
pub(crate) fn assert_default_chart_size(size: ChartSize) {
    assert_eq!(size, ChartSize::default());
}

#[cfg(test)]
pub(crate) fn assert_fixed_chart_size(size: ChartSize, width: f32, height: f32) {
    assert_eq!(size, ChartSize::Fixed { width, height });
}

#[cfg(test)]
pub(crate) fn assert_fill_chart_size(
    size: ChartSize,
    min_width: f32,
    min_height: f32,
    aspect_ratio: Option<f32>,
) {
    assert_eq!(
        size,
        ChartSize::Fill {
            min_width,
            min_height,
            aspect_ratio,
        }
    );
}

#[cfg(test)]
mod extra_tests {
    use super::*;

    #[test]
    fn test_layout_dimensions_ignores_invalid_aspect_ratio() {
        // Non-positive and non-finite aspect ratios should be ignored
        assert_eq!(
            ChartSize::fill()
                .min_size(300.0, 200.0)
                .aspect_ratio(0.0)
                .layout_dimensions(),
            (300.0, 200.0)
        );
        assert_eq!(
            ChartSize::fill()
                .min_size(300.0, 200.0)
                .aspect_ratio(-1.0)
                .layout_dimensions(),
            (300.0, 200.0)
        );
        assert_eq!(
            ChartSize::fill()
                .min_size(300.0, 200.0)
                .aspect_ratio(f32::NAN)
                .layout_dimensions(),
            (300.0, 200.0)
        );
        assert_eq!(
            ChartSize::fill()
                .min_size(300.0, 200.0)
                .aspect_ratio(f32::INFINITY)
                .layout_dimensions(),
            (300.0, 200.0)
        );
    }

    #[test]
    fn test_layout_dimensions_ignores_invalid_dimensions() {
        // Non-positive or non-finite min dimensions should prevent aspect adjustment
        assert_eq!(
            ChartSize::fill()
                .min_size(0.0, 200.0)
                .aspect_ratio(2.0)
                .layout_dimensions(),
            (0.0, 200.0)
        );
        let dims = ChartSize::fill()
            .min_size(300.0, f32::NAN)
            .aspect_ratio(2.0)
            .layout_dimensions();
        assert_eq!(dims.0, 300.0);
        assert!(dims.1.is_nan());
    }

    #[test]
    fn test_fixed_converted_to_fill_by_min_size() {
        let fixed = ChartSize::fixed(400.0, 300.0);
        let fill = fixed.min_size(200.0, 150.0);
        assert_eq!(
            fill,
            ChartSize::Fill {
                min_width: 200.0,
                min_height: 150.0,
                aspect_ratio: None,
            }
        );
    }

    #[test]
    fn test_fill_preserves_aspect_ratio_on_min_size() {
        let fill = ChartSize::fill()
            .min_size(300.0, 200.0)
            .aspect_ratio(2.0);
        let resized = fill.min_size(150.0, 100.0);
        assert_eq!(
            resized,
            ChartSize::Fill {
                min_width: 150.0,
                min_height: 100.0,
                aspect_ratio: Some(2.0),
            }
        );
    }

    #[test]
    fn test_layout_dimensions_when_already_matching_ratio() {
        // 400x200 has ratio 2.0, so no change needed
        assert_eq!(
            ChartSize::fill()
                .min_size(400.0, 200.0)
                .aspect_ratio(2.0)
                .layout_dimensions(),
            (400.0, 200.0)
        );
    }

    #[test]
    fn test_fill_factory() {
        assert_eq!(ChartSize::fill(), ChartSize::default());
    }
}
